    ret20 = c[-1] / c[-21] - 1 if len(c) >= 21 else float("nan")
    print(f"{a:10s} {str(dts[last_chg])[:10]:12s} flat={n_flat:3d} vol20={vol20*100:6.3f}% ret60={ret60*100:7.2f}% ret20={ret20*100:7.2f}%")

try:
