        room = [a for a, x in w.items() if x < cap - 1e-9]
        if not room:
            break
        p = {a: max(0.0, pref.get(a, 0.0)) for a in room}
        den = sum(p.values())
        if den <= 0:
            p = {a: 1.0 for a in room}
            den = len(room)
        for a in room:
            w[a] += excess * p[a] / den

    tot = sum(w.values())
    if tot <= 0:
