    vx = float(np.var(xs))
    b = float(np.cov(xs, ys)[0, 1] / vx) if vx > 1e-14 else 0.0
    for i, a in enumerate(assets):
        sig["dd_duration_120_resid"][a] = ys[i] - b * (xs[i] - xm)

