            sig["spx_beta_60"][a] = beta_last(r, r_spx)
        if "hs300_beta_60" in ens_ids:
            sig["hs300_beta_60"][a] = beta_last(r, r_300)
        if "cn10y_beta_60" in ens_ids:
            sig["cn10y_beta_60"][a] = beta_last(r, d_cn)
