    """Cross-sectional rank in [0,1]; missing -> 0.5."""
    valid = sorted((float(v), a) for a, v in values.items()
                   if v is not None and np.isfinite(float(v)))
    out = {a: 0.5 for a in assets}
    n = max(1, len(valid) - 1)
    for i, (_, a) in enumerate(valid):
        out[a] = i / n
    return out


