    try:
        d = json.load(open("../persistent/date.json"))
        tds = d.get("trading_days", [])
        cur = d.get("current_date")
        if ONLINE_START in tds and cur in tds:
            return (tds.index(cur) - tds.index(ONLINE_START)) % HORIZON == 0
    except Exception:
