    water-fill cap among live assets so no live weight can exceed `cap`.
    """
    if not frozen or len(frozen) >= len(assets) - 1:
        return w
    w = dict(w)
    live = [a for a in assets if a not in frozen]
    for a in frozen:
        w[a] = floor
