    tot = sum(w.values())
    if tot <= 0:
        return {a: 1.0 / len(assets) for a in assets}
    w = {a: x / tot for a, x in w.items()}
    # 2) water-fill cap among live assets (after renormalization)
    for _ in range(200):
        excess = sum(max(0.0, w[a] - cap) for a in live)
        if excess < 1e-12:
            break
        for a in live:
            w[a] = min(cap, w[a])
