    ens_ids = {fid for fid, _, _ in ens}

    r_spx = ret["SPX"]
    r_300 = ret["000300.SH"]
    d_cn = close["CN10Y"].pct_change()
    dxy = series(get_df("DXY"))
    r_dxy = dxy.pct_change() if dxy is not None else None
    comm_basket = panel[["XAU", "COPPER", "WTI"]].mean(axis=1)  # ew commodity basket

